  private static void useNonLeftAlignment(SNode content, SModel source) {
    for (SNode root : source.getRootNodes()) {
      SNode candidate = child(root, "content");
      for (SProperty property : candidate.getProperties()) {
        if ("align".equals(property.getName())) {
          String value = candidate.getProperty(property);
          if (value != null && !("left".equals(value))) {
            content.setProperty(property, value);
            return;
          }
        }
      }
    }
    throw new AssertionError("Missing non-left-aligned test fixture");
  }
